_EMBEDDED_SCRIPTS = {
    'scrape.py':
        '',
    'jd.py':
        '',
    'indiamart.py':
        '',
}


def _ensure_scripts() -> Path:
    """Extract embedded scraper scripts. Returns the scripts directory."""
    import base64 as _b64, zlib as _zlib
    scripts_dir = Path(__file__).parent.resolve() / '.scripts'
    scripts_dir.mkdir(exist_ok=True)
    for name, encoded in _EMBEDDED_SCRIPTS.items():
        path = scripts_dir / name
        # Re-extract if missing or size changed (script was updated)
        content = _zlib.decompress(_b64.b64decode(encoded)).decode('utf-8')
        if not path.exists() or path.read_text(encoding='utf-8') != content:
            tmp = path.with_suffix('.tmp')
            tmp.write_text(content, encoding='utf-8')
            tmp.replace(path)  # atomic on NTFS and Linux
    return scripts_dir

# --- bootstrap (only rich needed for the launcher itself) -----------------
def _bootstrap():
    needed = []
    for pkg in ['rich', 'openpyxl']:
        if importlib.util.find_spec(pkg) is None:
            needed.append(pkg)
    if needed:
        print(f"[first-run] installing {', '.join(needed)}...", file=sys.stderr, flush=True)
        subprocess.run(
            [sys.executable, "-m", "pip", "install", "--quiet", *needed],
            check=True,
        )

_bootstrap()


