HISTORY_FILE = Path(__file__).parent / '.last_searches.json'


def preflight_check() -> None:
    """Check internet, disk space, write permissions before anything runs."""
    import shutil as _shutil
    from urllib.request import urlopen

    console.print("[dim]Running system check...[/]", end=" ")
    problems: list[str] = []

    # 1. Internet
    try:
        urlopen('https://www.google.com', timeout=5).close()
    except Exception:
        problems.append(
            "No internet. Check your Wi-Fi/connection and try again."
        )

    # 2. Disk space (need at least 500 MB for browser cache)
    try:
        free_gb = _shutil.disk_usage(Path.home()).free / (1024**3)
        if free_gb < 0.5:
            problems.append(
                f"Only {free_gb:.1f} GB free on disk. Need at least 500 MB. "
                "Delete some files and try again."
            )
    except Exception:
        pass

    # 3. Detect if running from inside a zip (virtual Windows mount)
    script_path = Path(__file__).resolve()
    script_str = str(script_path).lower()
    if '.zip\\' in script_str or '.zip/' in script_str or 'temp\\' in script_str and 'extract' in script_str:
        problems.append(
            "You are running the script from INSIDE a ZIP file.\n"
            "    Please right-click the zip -> Extract All -> choose a folder\n"
            "    (e.g. Desktop), then run master_scrape.py from the extracted folder."
        )

    # 4. Write permission to output folder + round-trip test
    out_base = Path(__file__).parent.resolve() / 'output'
    try:
        out_base.mkdir(exist_ok=True)
        # Round-trip test: create subfolder, write file, read it back, delete
        test_dir = out_base / '.preflight_test'
        test_dir.mkdir(exist_ok=True)
        test_file = test_dir / 'test.xlsx'
        test_file.write_bytes(b'PK\x03\x04')  # fake xlsx header
        if test_file.read_bytes() != b'PK\x03\x04':
            raise OSError("Read-back mismatch")
        test_file.unlink()
        test_dir.rmdir()
    except Exception as e:
        problems.append(
            f"Can't create and write files in the output folder.\n"
            f"    Error: {e}\n"
            "    This usually means:\n"
            "    1. You're running from a ZIP file (extract it first!)\n"
            "    2. The folder is read-only\n"
            "    3. Antivirus is blocking file writes"
        )

    if problems:
        console.print("[bold red]FAILED[/]")
        for p in problems:
            console.print(f"  [red]X[/] {p}")
        console.print()
        sys.exit(1)
    console.print("[green]OK[/]")


def load_history() -> list[dict]:
    """Load recent searches from .last_searches.json."""
    if not HISTORY_FILE.exists():
        return []
    try:
        import json as _json
        return _json.loads(HISTORY_FILE.read_text()) or []
    except Exception:
        return []


def save_history(entry: dict) -> None:
    """Append a search to history, keep last 10."""
    try:
        import json as _json
        hist = load_history()
        hist = [entry] + [h for h in hist if h != entry]
        hist = hist[:10]
        HISTORY_FILE.write_text(_json.dumps(hist, indent=2))
    except Exception:
        pass


def friendly_error(exit_code: int, source_name: str) -> str:
    """Translate scraper exit codes into user-friendly messages."""
    if exit_code == 2:
        return (f"{source_name} was blocked (captcha or bot detection). "
                f"Try running in Visible mode and solve any captcha in the browser.")
    if exit_code == 130:
        return f"{source_name} was cancelled (Ctrl+C)."
    if exit_code == 1:
        return (f"{source_name} couldn't start. Check your internet and try again. "
                f"If it keeps failing, delete the .scripts folder and re-run.")
    return f"{source_name} failed with exit code {exit_code}. See logs above."


def open_folder(path: Path) -> None:
    """Open a folder in the OS file manager."""
    try:
        if os.name == 'nt':
            os.startfile(str(path))
        elif sys.platform == 'darwin':
            subprocess.Popen(['open', str(path)])
        else:
            subprocess.Popen(['xdg-open', str(path)])
    except Exception:
        pass


def count_xlsx_rows(path: Path) -> int:
    """Count data rows in an xlsx file (minus header)."""
    try:
        from openpyxl import load_workbook
        wb = load_workbook(path, read_only=True)
        total = 0
        for ws in wb.worksheets:
            total += max(0, ws.max_row - 1)
        wb.close()
        return total
    except Exception:
        return 0


def show_final_summary(out_dir: Path, start_time: float) -> None:
    """Rich final summary — row counts, time elapsed, open-folder option."""
    import time as _time
    from rich.table import Table as _Table

    elapsed = _time.monotonic() - start_time
    mins, secs = int(elapsed // 60), int(elapsed % 60)
    time_str = f"{mins}m {secs}s" if mins else f"{secs}s"

    if not out_dir.exists():
        console.print(Panel.fit(
            "[bold yellow]No output folder created.[/]\n"
            "[dim]All scrapers may have failed. Check the logs above.[/]",
            border_style="yellow",
        ))
        return

    xlsx_files = sorted(out_dir.glob('*.xlsx'))
    if not xlsx_files:
        console.print(Panel.fit(
            "[bold yellow]Output folder is empty.[/]\n"
            f"[dim]{out_dir}[/]",
            border_style="yellow",
        ))
        return

    table = _Table(show_header=True, border_style="green", padding=(0, 2))
    table.add_column("File", style="bold")
    table.add_column("Rows", justify="right")
    table.add_column("Size", justify="right")
    total_rows = 0
    for f in xlsx_files:
        rows = count_xlsx_rows(f)
        total_rows += rows
        size_kb = f.stat().st_size // 1024
        table.add_row(f.name, str(rows), f"{size_kb} KB")

    console.print()
    console.print(Panel(
        f"[bold green]Done in {time_str}[/]\n\n"
        f"Output folder: [cyan]{out_dir}[/]",
        border_style="green",
    ))
    console.print(table)
    console.print()

    # Offer to open folder
    if sys.stdin and sys.stdin.isatty():
        if Confirm.ask("[bold]Open output folder now?[/]", default=True):
            open_folder(out_dir)

